/** Original Opening Shift interface. All outcomes and finances come from the engine.
 * Interface drafts are tab-local and never count as submitted learner evidence.
 * Authored/reviewed 16 November 2026, America/Halifax. */
import {OPENING_CONTENT as C} from './content.js';
import * as art from './scene.js';

const esc=(v='')=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const list=v=>Array.isArray(v)?v:Object.values(v||{});
const ident=v=>String(v||'').replace(/[^a-z0-9_-]/gi,'-');
const number=v=>Number.isFinite(Number(v))?Number(v):0;
const icon=(name)=>`<svg viewBox="0 0 24 24" class="icon" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',phone:'<rect x="6" y="2" width="12" height="20" rx="3"/><path d="M10 5h4m-3 14h2"/>',kit:'<rect x="3" y="7" width="18" height="14" rx="3"/><path d="M8 7V4h8v3M3 12h18m-11 0v3h4v-3"/>',inspect:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6M7 10h6m-3-3v6"/>',cable:'<path d="M5 3v5m6-5v5M3 8h10v3a5 5 0 0 1-10 0zM8 16v2a3 3 0 0 0 6 0v-3m-1-5h5v5h-5z"/>',tests:'<path d="M2 12h5l3-7 4 14 3-7h5"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6"/>',note:'<path d="M6 3h9l4 4v14H6zM14 3v5h5M9 12h7M9 16h7"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 4m0 3h.01"/>',save:'<path d="M4 3h13l3 3v15H4zM8 3v6h8V3M8 21v-8h8v8"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',power:'<path d="M12 2v10M6 5a9 9 0 1 0 12 0"/>',wifi:'<path d="M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0M8 16a6 6 0 0 1 8 0M12 20h.01"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',alert:'<path d="m12 3 10 18H2zM12 9v5m0 3h.01"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',home:'<path d="m3 11 9-8 9 8M5 10v11h14V10M9 21v-8h6v8"/>',coin:'<circle cx="12" cy="12" r="9"/><path d="M15 8h-4a2 2 0 0 0 0 4h2a2 2 0 0 1 0 4H9m3-10v12"/>'})[name]||''}</svg>`;
const btn=(action,text,attrs='',style='button')=>`<button type="button" class="${style}" data-action="${action}" ${attrs}>${text}</button>`;
const badge=(text,tone='')=>`<span class="badge ${tone}">${esc(text)}</span>`;
const option=(value,label,current,disabled=false)=>`<option value="${esc(value)}" ${String(value)===String(current)?'selected':''} ${disabled?'disabled':''}>${esc(label)}</option>`;
const TABS=[['equipment','kit','Kit'],['devices','inspect','Devices'],['cables','cable','Cables'],['tests','tests','Tests'],['access','shield','Access'],['handover','note','Handover']];
const DRAFT_KEY='riverbend.clinic.opening.v1.ui-drafts';

export function mountOpeningUI(root,handlers){
  const {getView,send,onExport,onImport,onReset,onClear,onTakeControl,onRecover}=handlers;
  let view=getView(),panel='equipment',selectedDeviceId=null,selectedObservationId=null,modal=null,modalReturn=null,busy=false,closed=false,lastStatus=null;
  let guideId=C.guides[0].id,explanationKey='equipment',pendingFile=null,pasteText='',lastScope='',draftStorageFailed=false;
  let connection={fromDeviceId:'',fromPortId:'',toDeviceId:'',toPortId:'',itemId:''};
  let draftBook={};
  try{const parsed=JSON.parse(sessionStorage.getItem(DRAFT_KEY)||'{}');if(parsed&&typeof parsed==='object'&&!Array.isArray(parsed))draftBook=parsed;}catch{draftStorageFailed=true;}
  const disclosure=new Set();
  const openedInspections=new Set();
  root.innerHTML=`<div class="app-shell"><a class="skip-link" href="#workbench">Skip to clinic workbench</a><header class="topbar" data-region="header"></header><div data-region="storage"></div><main id="workbench" tabindex="-1"><div data-region="intro"></div><section data-region="focus"></section><div class="workspace-grid"><section class="clinic-panel" aria-label="Clinic floor plan"><div data-region="scene"></div><div data-region="feedback"></div></section><aside class="workspace-side" aria-label="Client and workbench"><div data-region="welcome"></div><div class="toolbox" data-toolbox><nav class="tool-tabs" role="tablist" aria-label="Workbench tools" data-region="tabs"></nav><section class="tool-panel" id="tool-panel" role="tabpanel" data-region="tool"></section></div></aside></div><footer class="app-footer" data-region="footer"></footer></main><div data-region="modal"></div><input id="opening-import-file" class="sr-only" type="file" accept=".json,application/json" tabindex="-1" aria-label="Choose Opening Shift progress JSON"><div class="sr-only" id="opening-live-status" role="status" aria-live="polite" aria-atomic="true"></div></div>`;
  const region=name=>root.querySelector(`[data-region="${name}"]`);
  const update=(name,html)=>{const el=region(name);if(el&&el.innerHTML!==html)el.innerHTML=html;};
  const scope=()=>`${view.campaignId}|${view.attemptId||`${view.mode}|${view.fixture}`}`;
  const bucket=()=>draftBook[scope()]||(draftBook[scope()]={campaignId:view.campaignId,attemptId:view.attemptId,mode:view.mode,fixture:view.fixture,explanations:{},settings:{},savedAt:''});
  const explanationDrafts=()=>bucket().explanations||(bucket().explanations={});
  const settingsDrafts=()=>bucket().settings||(bucket().settings={});
  const dirtyCount=()=>Object.values(draftBook).reduce((n,b)=>n+Object.keys(b.explanations||{}).length+Object.keys(b.settings||{}).length,0);
  const currentDirty=()=>Object.keys(explanationDrafts()).length+Object.keys(settingsDrafts()).length;
  const explanationBase=key=>JSON.stringify(view.explanations?.[key]||{});
  const device=id=>list(view.devices).find(d=>d.id===id);
  const inventory=id=>list(view.inventory).find(i=>i.id===id);
  const locationName=id=>list(view.locations).find(l=>l.id===id)?.label||id||'Not placed';
  const deviceName=id=>device(id)?.roleLabel||device(id)?.label||id||'No device';
  const readonly=()=>['readonly','starting'].includes(view.storage?.mode);
  const frozen=()=>view.phase!=='active';
  const disabled=(extra=false,allowFrozen=false)=>busy||readonly()||(!allowFrozen&&frozen())||extra?'disabled':'';
  const practice=()=>view.mode==='practice';
  const nurse=()=>device(view.nurseDeviceId);
  const currentRoom=()=>nurse()?.locationId;
  const artwork=(kind,options={})=>art.renderDeviceArtwork?.(kind,options)||'';
  function saveDrafts(){
    bucket().savedAt=new Date().toISOString();
    try{sessionStorage.setItem(DRAFT_KEY,JSON.stringify(draftBook));draftStorageFailed=false;}catch{draftStorageFailed=true;}
  }
  function rescueText(){return ['OPENING SHIFT — UNSUBMITTED DRAFT RESCUE','These are interface drafts, NOT submitted evidence. They may belong to earlier attempts. Review before applying.','',...Object.entries(draftBook).filter(([,b])=>Object.keys(b.explanations||{}).length+Object.keys(b.settings||{}).length).flatMap(([id,b])=>[`CONTEXT: ${id}`,`Mode: ${b.mode}; fixture: ${b.fixture}; last edit: ${b.savedAt||'unknown'}`,...Object.entries(b.explanations||{}).flatMap(([k,d])=>[`\n${k.toUpperCase()} — UNSUBMITTED`,d.text||'[No written draft]',d.oral?'Requested oral review, not yet submitted.':'']),...Object.entries(b.settings||{}).flatMap(([id,d])=>[`\nUNAPPLIED SETTINGS: ${id}`,JSON.stringify(d,null,2)]),'\n'])].join('\n');}
  function focusSnapshot(){const el=document.activeElement;if(!el||!root.contains(el))return null;return{id:el.id,attrs:Object.fromEntries(Object.entries(el.dataset)),start:el.selectionStart,end:el.selectionEnd,scrollTop:el.scrollTop};}
  function restoreFocus(f){if(!f)return false;let el=f.id?root.querySelector(`#${CSS.escape(f.id)}`):null;if(!el&&Object.keys(f.attrs).length)el=[...root.querySelectorAll('[data-action],[data-draft]')].find(e=>Object.entries(f.attrs).every(([k,v])=>e.dataset[k]===v));if(el&&!el.disabled&&!el.closest('[hidden]')){el.focus({preventScroll:true});if(typeof f.start==='number'&&el.setSelectionRange){try{el.setSelectionRange(f.start,f.end);el.scrollTop=f.scrollTop;}catch{}}return true;}return false;}
  function finishWork(originalFocus){
    const latestFocus=focusSnapshot();busy=false;render();
    if(!restoreFocus(latestFocus||originalFocus))root.querySelector(modal?'.dialog-title':'#panel-heading')?.focus({preventScroll:true});
  }
  function announce(message){root.querySelector('#opening-live-status').textContent=message||'';}
  function showStatus(message,kind='info'){lastStatus={message:String(message||''),kind:kind===true?'error':kind===false?'info':kind};renderFeedback();announce(lastStatus.message);}
  function renderFeedback(){update('feedback',lastStatus?`<div class="feedback ${esc(lastStatus.kind)}">${icon(lastStatus.kind==='error'?'alert':lastStatus.kind==='success'?'check':'inspect')}<span>${esc(lastStatus.message)}</span></div>`:'');}
  function openModal(type,extra={}){modalReturn=focusSnapshot();modal={type,...extra};renderModal();requestAnimationFrame(()=>root.querySelector('.dialog-title')?.focus({preventScroll:true}));}
  function closeModal(){modal=null;update('modal','');if(!restoreFocus(modalReturn))root.querySelector('[data-action="progress"]')?.focus({preventScroll:true});}
  function pageTitle(){return view.phase==='settled'?'Shift handed over':view.phase==='delivered'?'Ready for your receipt':practice()?'Try, inspect, try again.':'Your clinic. Your next move.';}
  function header(){return `<a class="brand" href="./opening-shift.html" aria-label="Opening Shift home"><span class="brand-mark" aria-hidden="true"><i></i><i></i><i></i><i></i></span><span><strong>Opening Shift</strong><small>Riverbend Community Clinic</small></span></a><div class="header-actions">${practice()?badge('FREE REHEARSAL','practice'):badge('CLIENT JOB','plain')}${btn('phone',icon('phone')+'<span>Client</span>','','button button-quiet')}${btn('help',icon('help')+'<span>Guides</span>','','button button-quiet')}${btn('progress',icon('save')+'<span>Progress</span>','','button button-quiet')}</div>`;}
  function storage(){const s=view.storage||{mode:'memory',label:'Progress stays in this browser',detail:'Download progress for your own copy.'};const warning=['readonly','memory','error','starting'].includes(s.mode);return `<div class="storage-strip ${warning?'storage-warning':''}"><span class="storage-dot" aria-hidden="true"></span><strong>${esc(s.label)}</strong>${warning?`<span>${esc(s.detail)}</span>`:'<span class="storage-short">Download a copy before changing devices.</span>'}${s.canTakeControl?btn('confirm-takeover','Review & take control','','text-button'):''}${draftStorageFailed?'<span>Draft backup unavailable: keep this tab open or download your drafts.</span>':''}${dirtyCount()?btn('export-drafts',`${dirtyCount()} unsubmitted ${dirtyCount()===1?'draft':'drafts'}`,'','text-button'):''}</div>`;}
  function economy(compact=false){const e=view.economy||{};return `<div class="accounts ${compact?'accounts-compact':''}"><div class="account equipment-account"><span>${icon('kit')} Equipment allowance</span><strong>${practice()?'Free kit':`${number(e.remaining)} <small>/ ${number(e.allowance)}</small>`}</strong><small>${practice()?'Rehearsal purchases cost 0':`${number(e.spent)} spent · client’s credits`}</small></div><div class="account fee-account"><span>${icon('coin')} Contractor fee</span><strong>${practice()?'No earnings':`${number(e.net)} <small>credits</small>`}</strong><small>${practice()?'Practice does not complete the job':`${number(e.reserved)} guide cost · ${number(e.minutes)} simulated min`}</small></div></div>`;}
  function intro(){return `<div class="mission-heading"><div><p class="eyebrow">${view.briefReviewed?practice()?'FREE REHEARSAL · YOUR CLIENT JOB IS PRESERVED':'INDEPENDENT TECHNOLOGY JOB':'A NEW REQUEST FROM ARI'}</p><h1>${view.briefReviewed?pageTitle():'One desk works.<br>Two rooms are waiting.'}</h1>${!view.briefReviewed?`<p class="heading-deck">${esc(C.tagline)}</p>`:''}</div>${view.briefReviewed?economy(true):'<div class="no-timer">'+icon('clock')+'<span>Afternoon shift<br><strong>No real-time countdown</strong></span></div>'}</div>`;}
  function focus(){if(!view.briefReviewed)return '';const goals=C.goals[view.learningFocus?.stageId||view.stageId]||C.goals.build;return `<div class="focus-strip"><div class="next-action"><span class="eyebrow">${esc(goals.title)}</span><strong>${esc(view.learningFocus?.nextAction||'Choose your next action.')}</strong></div><ul class="current-goals">${goals.items.slice(0,3).map(g=>`<li>${esc(g.text)}</li>`).join('')}</ul></div>`;}
  function roomButtons(){return `<div class="room-buttons" role="group" aria-label="Move nurse between exam rooms">${['location.exam-a','location.exam-b'].map((id,i)=>btn('move-nurse',`Room ${i?'B':'A'}`,`data-location-id="${id}" aria-pressed="${currentRoom()===id}" ${disabled()}`,`button button-room ${currentRoom()===id?'selected':''}`)).join('')}</div>`;}
  function observationLabel(o){return o?.stale?'Earlier result · repeat test':o?.pass?(o.expectedDenied?'Expected denial confirmed':'Test passed'):'Test needs attention';}
  function resultTone(o){return o?.stale?'stale':o?.pass?'pass':'fail';}
  function scene(){
    const welcome=!view.briefReviewed;
    const observations=list(view.observations);
    const o=observations.find(x=>x.id===selectedObservationId)||observations[0];
    const anchors=art.getDeviceAnchors?.(view)||{};
    const devices=list(view.devices);
    const pins=welcome?'':Object.entries(anchors).map(([id,a])=>btn('select-device','<span class="pin-dot" aria-hidden="true"></span><span class="sr-only">Inspect '+esc(deviceName(id))+'</span>',`data-device-id="${esc(id)}" title="Inspect ${esc(deviceName(id))}" style="left:${number(a.x)/9.6}%;top:${number(a.y)/6.2}%" aria-pressed="${selectedDeviceId===id}"`,'device-pin')).join('');
    const header=`<div class="scene-heading"><div><p class="eyebrow">THE CLINIC FLOOR</p><h2>Make the connections count.</h2></div>${welcome?badge('LOCAL NETWORK','plain'):btn('phone',icon('phone')+' Ask the client','','button button-small button-light')}</div>`;
    const canvas=`<div class="clinic-scene">${art.renderScene(view,{selectedDeviceId,selectedObservationId:o?.id})}${pins}</div>`;
    if(welcome)return header+canvas+`<div class="scene-caption"><span>${icon('home')} One local clinic network</span><span>Original fictional clinic · no patient data</span></div>`;
    const commands=`<div class="scene-command"><div><strong>Move Sam, then test here</strong><small>${esc(locationName(currentRoom()))}</small></div>${roomButtons()}${btn('probe',icon('tests')+' Run nurse here',`data-test-id="nurse" ${disabled(!nurse())}`,'button button-primary')}</div>`;
    const deviceRail=`<div class="device-rail" role="group" aria-label="Select a device">${devices.map(d=>btn('select-device',esc(d.roleId==='role.records'?'Service host':d.roleLabel),`data-device-id="${esc(d.id)}" aria-pressed="${selectedDeviceId===d.id}"`,'device-chip')).join('')}</div>`;
    const result=o?`<div class="scene-result ${resultTone(o)}"><div>${badge(observationLabel(o),resultTone(o))}<strong>${esc(o.label||o.testId)} · ${esc(locationName(o.locationId))}</strong></div><p>${esc(o.message)}</p>${btn('panel','View test record','data-panel="tests"','text-button')}</div>`:'<div class="scene-result neutral"><strong>Your test path will appear here.</strong><p>Connections show the setup. Run a test to record an actual service result.</p></div>';
    return header+canvas+commands+deviceRail+result;
  }
  function welcome(){if(view.briefReviewed)return '';return `<div class="phone-card welcome-phone"><div class="phone-meta"><span class="avatar" aria-hidden="true">A</span><div><strong>Ari</strong><small>Clinic coordinator · client request</small></div><span class="message-dot" aria-hidden="true"></span></div><p class="eyebrow">OPENING SHIFT</p><h2>${esc(C.phone.greeting)}</h2><p>${esc(C.phone.brief[0])}</p><p class="phone-signoff">Choose the kit. Find the cause.<br>Leave a working shift.</p>${btn('review-brief','Review job '+icon('arrow'),disabled(false,true),'button button-primary button-wide')}${btn('practice',icon('tests')+' Start a free rehearsal','','button button-wide button-light')}${economy()}<p class="small-copy">Tests, inspection and reading time are free. Only accepted guide consultations affect the client fee.</p><a href="./index.html" class="legacy-link">New to networks? Open the separate bootcamp ${icon('arrow')}</a></div>`;}
  function tabs(){return TABS.map(([id,i,label])=>btn('panel',icon(i)+`<span>${label}</span>`,`id="tab-${id}" data-panel="${id}" role="tab" aria-selected="${panel===id}" aria-controls="tool-panel" tabindex="${panel===id?'0':'-1'}"`,'tool-tab')).join('');}
  function panelHeader(eyebrow,title,copy=''){return `<div class="panel-heading"><p class="eyebrow">${eyebrow}</p><h2 id="panel-heading" tabindex="-1">${title}</h2>${copy?`<p>${copy}</p>`:''}</div>`;}
  function equipmentPanel(){const chosen=list(view.objectives).find(o=>o.id==='objective.opening.equipment')?.met;return panelHeader('01 · EQUIPMENT','A kit that fits Sam','Ask about the work, then choose a portable device.')+`<div class="equipment-choices">${C.equipmentOptions.map(o=>{const i=inventory(o.itemId),s=list(view.shop).find(s=>s.itemId===o.itemId);return `<article class="equipment-card ${i?.installed?'active':''}"><div class="equipment-art">${artwork(o.kind,{powered:i?.installed,label:o.title})}</div><div><div class="card-title"><h3>${esc(o.title)}</h3>${i?.installed?badge(chosen?'Chosen':'Currently active',chosen?'pass':'plain'):badge(i?.owned?'Retained':`${number(s?.price)} credits`,'plain')}</div><p>${esc(o.benefit)}</p><p class="tradeoff">${esc(o.tradeoff)}</p>${i?.owned?btn('assign-nurse',i.installed?(chosen?'Keep this choice':'Keep this laptop'):'Use this device',`data-item-id="${o.itemId}" ${disabled()}`,'button button-small button-primary'):btn('buy',`Buy tablet · ${number(s?.price)} credits`,`data-sku="tablet" ${disabled(!s?.canBuy)}`,'button button-small button-primary')}${i?.returnable?btn('return-item',`Return · ${number(i.paidPrice)} credit refund`,`data-item-id="${i.id}" ${disabled()}`,'text-button'):''}</div></article>`;}).join('')}</div><details data-disclosure="replacement"><summary>What happens when I switch devices?</summary><p>${esc(C.replacementNote)}</p></details><h3 class="section-title">Complete the connection</h3><div class="infrastructure-cards">${C.infrastructure.map(o=>{const i=inventory(o.itemId),s=list(view.shop).find(s=>s.itemId===o.itemId);return `<article class="infrastructure-card"><div class="infrastructure-title">${icon(o.kind==='ethernet-cable'?'cable':'wifi')}<h4>${esc(o.title)}</h4>${badge(i?.installed?'Installed':i?.owned?'In stock':`${number(s?.price)} credits`,i?.installed?'plain':'')}</div><p>${esc(o.text)}</p><div class="button-row">${!i?.owned?btn('buy',`Buy · ${number(s?.price)} credits`,`data-sku="${o.sku}" ${disabled(!s?.canBuy)}`,'button button-small button-light'):o.kind==='ethernet-cable'?btn('panel','Connect ports','data-panel="cables"','button button-small button-light'):i.installed?btn('select-device','Inspect & power',`data-device-id="${esc(i.deviceId)}"`,'button button-small button-light'):btn('install',`Install in equipment room`,`data-item-id="${o.itemId}" ${disabled()}`,'button button-small button-light')}${i?.returnable?btn('return-item',`Return for ${number(i.paidPrice)}`,`data-item-id="${i.id}" ${disabled()}`,'text-button'):''}${i?.installed&&o.kind!=='ethernet-cable'?btn('uninstall',`Uninstall`,`data-item-id="${i.id}" ${disabled()}`,'text-button'):''}</div></article>`;}).join('')}</div><p class="small-copy">Unspent allowance stays with the client. Purchases and returns never increase your contractor fee.</p>`;}
  function networkCard(){return `<details data-disclosure="network"><summary>Clinic network card & used addresses</summary><div class="network-facts"><span>Network <code>${esc(view.network?.cidr)}</code></span><span>Mask <code>${esc(view.network?.mask)}</code></span></div><ul class="address-list">${list(view.devices).filter(d=>d.address).map(d=>`<li><span>${esc(d.roleId==='role.records'?'Service host':d.roleLabel)}</span><code>${esc(d.address)}</code></li>`).join('')}</ul><p class="small-copy">Compare the actual device settings. Applying a value does not run a service test.</p></details>`;}
  function devicesPanel(){const d=device(selectedDeviceId)||nurse()||list(view.devices)[0];if(!d)return panelHeader('02 · INSPECT','Choose a device','Install equipment from the Kit tab first.');selectedDeviceId=d.id;const draft=settingsDrafts()[d.id]||{},inspection=list(view.inspections).find(x=>x.targetId===d.id),hasHost=d.address!==''&&!d.capabilities?.includes('bridge');return panelHeader('02 · INSPECT','Look before you change','Choose any device on the clinic plan or from this list.')+`<label for="inspect-device">Device</label><select id="inspect-device" data-action="device-select">${list(view.devices).map(x=>option(x.id,`${x.roleId==='role.records'?'Service host':x.roleLabel} · ${x.label}`,d.id)).join('')}</select><div class="device-summary"><div class="device-summary-art">${artwork(d.kind,{powered:d.powered,selected:true})}</div><div><h3>${esc(d.label)}</h3><p>${esc(locationName(d.locationId))}</p>${badge(d.powered?'Power on':'Power off',d.powered?'plain':'warn')}${badge(d.wifiApId?'Wi-Fi associated':d.capabilities?.includes('wifi')?'Wi-Fi not associated':'Ethernet device','plain')}</div></div><div class="button-row">${btn('inspect-device',icon('inspect')+' Record inspection',`data-device-id="${esc(d.id)}" ${disabled()}`,'button button-primary')}${btn('power',icon('power')+` Turn ${d.powered?'off':'on'}`,`data-device-id="${esc(d.id)}" data-on="${!d.powered}" ${disabled()}`,'button button-light')}</div><p class="small-copy">${inspection?inspection.stale?'Earlier inspection recorded. Inspect again if you need a current record.':'Current inspection is in your evidence.':'Record an inspection to include what you actually checked in your evidence.'}</p>${hasHost?`<form class="settings-form" data-form="address" data-device-id="${esc(d.id)}"><div class="section-heading"><h3>IP settings</h3><span data-setting-status="${esc(d.id)}">${draft.address!==undefined||draft.mask!==undefined?badge('Unapplied draft','warn'):badge('Current settings','plain')}</span></div><label for="address-${ident(d.id)}">Static IPv4 address</label><input id="address-${ident(d.id)}" name="address" type="text" inputmode="decimal" autocomplete="off" spellcheck="false" maxlength="64" data-draft="setting" data-field="address" data-device-id="${esc(d.id)}" value="${esc(draft.address??d.address)}"><label for="mask-${ident(d.id)}">Subnet mask</label><input id="mask-${ident(d.id)}" name="mask" type="text" inputmode="decimal" autocomplete="off" spellcheck="false" maxlength="64" data-draft="setting" data-field="mask" data-device-id="${esc(d.id)}" value="${esc(draft.mask??d.mask)}"><button class="button button-light" type="submit" ${disabled()}>Apply address & mask</button></form>${networkCard()}`:''}${d.capabilities?.includes('wifi')?`<form class="wifi-form" data-form="wifi" data-device-id="${esc(d.id)}"><h3>${icon('wifi')} Wi-Fi association</h3><label for="wifi-${ident(d.id)}">Access point</label><select id="wifi-${ident(d.id)}" name="apDeviceId" data-draft="setting" data-field="wifiApId" data-device-id="${esc(d.id)}">${option('','Not associated',draft.wifiApId??d.wifiApId??'')}${list(view.devices).filter(x=>x.kind==='access-point').map(x=>option(x.id,`${x.label} · ${x.powered?'on':'off'}`,draft.wifiApId??d.wifiApId)).join('')}</select><button type="submit" class="button button-light" ${disabled()}>Apply Wi-Fi choice</button><p class="small-copy">A Wi-Fi association is one part of the path. Use a service test to check the whole route.</p></form>`:''}<details data-disclosure="ports-${ident(d.id)}"><summary>Ports, placement & ${d.id===view.serverDeviceId?'services':'equipment'}</summary><ul class="port-list">${list(d.ports).map(p=>`<li><span>${icon(p.medium==='wifi'?'wifi':'cable')}${esc(p.label)}</span><strong>${p.medium==='wifi'?(d.kind==='access-point'?'Radio':d.wifiApId?'Associated':'Not associated'):p.cableId?'Cable connected':'Available'}</strong></li>`).join('')}</ul>${btn('panel','Open cable controls','data-panel="cables"','button button-small button-light')}<form data-form="place" data-device-id="${esc(d.id)}"><label for="placement-${ident(d.id)}">Physical location</label><select id="placement-${ident(d.id)}" name="locationId">${list(view.locations).map(l=>option(l.id,l.label,d.locationId)).join('')}</select><button type="submit" class="button button-small button-light" ${disabled()}>Move this device</button></form>${d.id===view.serverDeviceId?`<p>Shared services are ${view.serverEnabled?'running':'stopped'}.</p>${btn('services',`${view.serverEnabled?'Stop':'Start'} shared services`,`data-enabled="${!view.serverEnabled}" ${disabled()}`,'button button-small button-light')}`:''}</details>`;}
  function syncConnection(){const eth=list(view.devices).filter(d=>list(d.ports).some(p=>p.medium==='ethernet'));if(!eth.some(d=>d.id===connection.fromDeviceId))connection.fromDeviceId=view.apDeviceId||eth[0]?.id||'';if(!eth.some(d=>d.id===connection.toDeviceId))connection.toDeviceId=view.switchDeviceId||eth[1]?.id||'';for(const end of ['from','to']){const ports=list(device(connection[`${end}DeviceId`])?.ports).filter(p=>p.medium==='ethernet');if(!ports.some(p=>p.id===connection[`${end}PortId`]&&!p.cableId))connection[`${end}PortId`]=ports.find(p=>!p.cableId)?.id||'';}const cables=list(view.inventory).filter(i=>i.kind==='ethernet-cable'&&i.owned&&!i.cableId);if(!cables.some(i=>i.id===connection.itemId))connection.itemId=cables.find(i=>i.id==='item.uplink')?.id||cables[0]?.id||'';}
  function endpoint(end){const eth=list(view.devices).filter(d=>list(d.ports).some(p=>p.medium==='ethernet')),d=device(connection[`${end}DeviceId`]);return `<fieldset><legend>${end==='from'?'First end':'Second end'}</legend><label for="${end}-device">Device</label><select id="${end}-device" data-connection="${end}DeviceId">${eth.map(d=>option(d.id,d.roleId==='role.records'?'Service host':d.roleLabel,connection[`${end}DeviceId`])).join('')}</select><label for="${end}-port">Ethernet port</label><select id="${end}-port" data-connection="${end}PortId">${option('','Choose an available port',connection[`${end}PortId`])}${list(d?.ports).filter(p=>p.medium==='ethernet').map(p=>option(p.id,`${p.label}${p.cableId?' · occupied':' · available'}`,connection[`${end}PortId`],!!p.cableId)).join('')}</select></fieldset>`;}
  function cableSummary(c){const label=(id,pid)=>`${deviceName(id)} · ${list(device(id)?.ports).find(p=>p.id===pid)?.label||pid}`;return `${label(c.fromDeviceId,c.fromPortId)} ↔ ${label(c.toDeviceId,c.toPortId)}`;}
  function cablesPanel(){syncConnection();const free=list(view.inventory).filter(i=>i.kind==='ethernet-cable'&&i.owned&&!i.cableId);return panelHeader('03 · CONNECT','Choose two real ports','Pick both ends and an owned cable. No dragging needed.')+`<form data-form="connect"><label for="cable-item">Cable from your stock</label><select id="cable-item" data-connection="itemId">${option('',free.length?'Choose a cable':'No free cable in stock',connection.itemId)}${free.map(i=>option(i.id,i.label,connection.itemId)).join('')}</select><div class="connection-ends">${endpoint('from')}${endpoint('to')}</div><button type="submit" class="button button-primary button-wide" ${disabled(!connection.itemId||!connection.fromPortId||!connection.toPortId)}>Connect these ports</button></form>${!free.length?btn('panel','Open kit & cable stock','data-panel="equipment"','text-button'):''}<h3 class="section-title">Cable record</h3><div class="cable-record">${list(view.inventory).filter(i=>i.kind==='ethernet-cable'&&i.owned).map(i=>{const cable=list(view.cables).find(c=>c.itemId===i.id||c.id===i.cableId);return `<article class="cable-item"><div class="card-title"><h4>${esc(i.label)}</h4>${badge(cable?'Connected':'In stock',cable?'plain':'warn')}</div><p>${cable?esc(cableSummary(cable)):i.rememberedEndpoints?'Disconnected. Its previous endpoints are remembered; this cable carries no traffic.':'Available to connect two Ethernet ports.'}</p><div class="button-row">${btn('inspect-cable','Inspect cable',`data-item-id="${i.id}" ${disabled()}`,'button button-small button-light')}${cable?btn('disconnect','Disconnect',`data-cable-id="${esc(cable.id)}" ${disabled()}`,'text-button'):''}</div></article>`;}).join('')}</div><p class="small-copy">A line on the plan is a physical link. Only a recorded test can show whether the service works.</p>`;}
  function pathText(o){const p=list(o.pathIds);if(!p.length)return 'No complete path was returned by this test.';return p.map(id=>device(id)?deviceName(id):list(view.cables).some(c=>c.id===id)?'Ethernet cable':String(id).includes('wifi')?'Wi-Fi link':id).join(' → ');}
  function testsPanel(){const all=list(view.observations);return panelHeader('04 · TEST','Prove it where Sam works','Move to a room, then run the nurse test there. Other checks keep reception and access in view.')+`<div class="test-here"><strong>Nurse is in ${esc(locationName(currentRoom()))}</strong>${roomButtons()}${btn('probe',icon('tests')+' Run nurse here',`data-test-id="nurse" ${disabled()}`,'button button-primary button-wide')}</div><div class="test-actions">${[['reception','Reception bookings'],['nurse-bookings','Nurse bookings'],['access','Staff restrictions & outsiders']].map(([id,label])=>btn('probe',label,`data-test-id="${id}" ${disabled()}`,'button button-light')).join('')}</div><details data-disclosure="test-all"><summary>Run the complete check set here</summary><p>This tests the nurse only in the current room. Visit the other room and run its nurse test yourself.</p>${btn('probe','Run checks in this location',`data-test-id="all" ${disabled()}`,'button button-small button-light')}</details><h3 class="section-title">Required recorded checks</h3><ul class="checklist">${list(view.requiredTests).map(r=>`<li class="${r.met?'met':''}"><span class="check-symbol" aria-hidden="true">${r.met?'✓':'○'}</span><div><strong>${esc(r.label)}</strong><small>${r.met?'Fresh player test recorded':r.observation?'Latest recorded test needs attention':'A fresh explicit test is still needed'}</small></div></li>`).join('')}</ul><details data-disclosure="observations" open><summary>Your test history · ${all.length}</summary>${all.length?all.slice(0,30).map(o=>`<article class="test-record ${resultTone(o)}"><div class="card-title">${badge(observationLabel(o),resultTone(o))}<small>${esc(locationName(o.locationId))}</small></div><h4>${esc(o.label||o.testId)}</h4><p>${esc(o.message)}</p><details data-disclosure="path-${ident(o.id)}"><summary>Actual path & test code</summary><p class="path-copy">${esc(pathText(o))}</p><code>${esc(o.code)}</code><p class="small-copy">Recorded at technical revision ${number(o.testedTechnicalRevision)}${o.stale?' · earlier configuration':''}.</p></details>${btn('show-observation',selectedObservationId===o.id?'Shown on plan':'Show result on plan',`data-observation-id="${esc(o.id)}" aria-pressed="${selectedObservationId===o.id}"`,'text-button')}</article>`).join(''):'<p>No tests yet. Inspection and test controls are free.</p>'}</details><details data-disclosure="current-checks"><summary>Current engine checks · not player evidence</summary><p>${esc(C.checksNote)}</p>${list(view.currentResults).map(o=>`<p class="model-check"><strong>${esc(o.label)}</strong><span>${esc(o.code)} — ${esc(o.message)}</span></p>`).join('')}</details>`;}
  function accessPanel(){return panelHeader('05 · ACCESS','Who should handle bookings?','Both staff work and sensible restrictions matter. Ask Ari about the workflow, then make an explicit choice.')+`<div class="button-row">${btn('phone',icon('phone')+' Ask about the work','','button button-small button-light')}${badge(view.policyDecision?'Decision recorded':'Choose or keep a policy',view.policyDecision?'plain':'warn')}</div><div class="policy-cards">${list(view.policies).map(p=>{const copy=C.policies[p.id]||p,current=view.policy?.id===p.id;return `<article class="policy-card ${current?'selected':''}"><div class="card-title"><h3>${esc(copy.title||p.label)}</h3>${current?badge('Current','plain'):''}</div><p>${esc(copy.description)}</p><p class="policy-tradeoff"><strong>Trade-off</strong> ${esc(copy.tradeoff||'')}</p><details data-disclosure="policy-${ident(p.id)}"><summary>What should the test show?</summary><p>${esc(copy.consequence||'')}</p></details>${btn('policy',current?(copy.retainLabel||'Keep this policy'):'Choose this policy',`data-policy-id="${p.id}" ${disabled()}`,`button button-small ${current?'button-primary':'button-light'}`)}</article>`;}).join('')}</div>${view.policyDecision?`<div class="client-reply"><strong>Ari · coordinator</strong><p>${esc(C.policies[view.policy?.id]?.clientReply||'Decision recorded. Test its consequences.')}</p></div>`:''}${btn('probe','Test nurse bookings',`data-test-id="nurse-bookings" ${disabled()}`,'button button-light')}${btn('probe','Test staff restrictions & outsiders',`data-test-id="access" ${disabled()}`,'button button-light')}`;}
  function handoverPanel(){const prompt=C.explanationPrompts.find(p=>p.key===explanationKey)||C.explanationPrompts[0],saved=view.explanations?.[prompt.key]||{},draft=explanationDrafts()[prompt.key],value=draft||saved,conflict=draft&&(draft.needsReview||draft.base!==explanationBase(prompt.key));return panelHeader('06 · HANDOVER',view.phase==='active'?'Leave a clear handover':'Your shift record',C.evidenceNote)+`<div class="explanation-nav" role="group" aria-label="Choose a handover prompt">${C.explanationPrompts.map((p,i)=>{const e=view.explanations?.[p.key],dirty=!!explanationDrafts()[p.key];return btn('explanation',`<span>${i+1}</span>${esc(['Equipment','Repair','Access','Limits'][i])}${dirty?'<i aria-label="unsubmitted draft">•</i>':e?.submitted&&!e.stale?'<i aria-label="submitted">✓</i>':''}`,`data-key="${p.key}" aria-pressed="${explanationKey===p.key}"`,'explanation-tab');}).join('')}</div><form data-form="explanation" data-key="${prompt.key}" class="explanation-form"><h3>${esc(prompt.title)}</h3><label for="explanation-${prompt.key}">${esc(prompt.prompt)}</label><textarea id="explanation-${prompt.key}" name="text" rows="6" maxlength="2000" data-draft="explanation" data-key="${prompt.key}" placeholder="${esc(prompt.placeholder)}">${esc(value.text||'')}</textarea><label class="checkbox-label"><input type="checkbox" name="oral" data-draft="oral" data-key="${prompt.key}" ${value.oral?'checked':''}><span>${esc(prompt.oralLabel)}</span></label><p class="draft-status" data-draft-status="${prompt.key}">${draft?'Unsubmitted draft · stored only in this tab':saved.stale?'Policy context changed · review and resubmit':saved.submitted?'Submitted for teacher review · no quality grade awarded':'Write a short explanation or arrange oral review.'}</p>${conflict?'<div class="inline-warning">The submitted record changed since this draft began. Review the current text below before choosing to replace it.</div><details data-disclosure="draft-conflict"><summary>Current submitted explanation</summary><p class="exact-text">'+esc(saved.text||'[No written explanation]')+'</p></details>':''}<button type="submit" class="button button-primary" ${disabled()}>${conflict?'Replace submitted explanation with this draft':'Save this explanation'}</button></form><details data-disclosure="handover-checklist"><summary>Full handover checklist · ${list(view.objectives).filter(o=>o.met).length}/${list(view.objectives).length}</summary><ul class="checklist">${list(view.objectives).map(o=>`<li class="${o.met?'met':''}"><span class="check-symbol" aria-hidden="true">${o.met?'✓':'○'}</span><div><strong>${esc(o.label)}</strong><small>${esc(o.detail)}</small></div></li>`).join('')}</ul></details>${view.phase==='active'?`<div class="handover-action"><strong>${practice()?'Rehearsal evidence':view.ready?'Ready for handover':'Your evidence is taking shape'}</strong><p>${practice()?'Free rehearsal earns no fee and cannot complete the independent job. You can download this practice record.':view.ready?'Review your final evidence. Handover freezes the delivered work and contractor fee.':'Save your explanations, then review the full checklist. The engine checks the actual setup again at handover.'}</p>${practice()?btn('export','Download rehearsal evidence','data-format="evidence"','button button-primary'):btn('review-handover','Review & hand over',`${disabled()}`,'button button-primary')}${practice()?btn('return-client','Return to the independent job',disabled(false,true),'button button-light'):''}</div>`:`<div class="handover-action completed"><h3>Delivery recorded</h3><p>The delivered evidence and fee are frozen. Your explanations are still pending teacher review.</p>${view.phase==='delivered'?btn('settle',`Collect ${number(view.economy?.net)} credit fee`,`${disabled(false,true)}`,'button button-primary'):badge(`${number(view.economy?.wallet)} credits received`,'pass')}${btn('export','Download delivery evidence','data-format="evidence"','button button-light')}</div>`}<details data-disclosure="boundaries"><summary>Model limits & discussion prompts</summary><ul>${C.boundaries.map(b=>`<li>${esc(b)}</li>`).join('')}</ul>${C.contentConnections.map(c=>`<p><strong>${esc(c.concept)}</strong> · ${esc(c.question)}</p>`).join('')}</details>`;}
  function tool(){return({equipment:equipmentPanel,devices:devicesPanel,cables:cablesPanel,tests:testsPanel,access:accessPanel,handover:handoverPanel})[panel]();}
  function footer(){return `<span>Opening Shift · ${esc(view.buildVersion||C.version)}</span><span>One fictional local network. No patient information.</span><a href="./index.html">Bootcamp & earlier clinic</a>${btn('about','About this model','','text-button')}`;}
  function phoneBody(){return `<div class="phone-meta"><span class="avatar" aria-hidden="true">A</span><div><strong>Ari · clinic coordinator</strong><small>${esc(C.phone.subject)}</small></div></div>${C.phone.brief.map(p=>`<p>${esc(p)}</p>`).join('')}<h3>Ask the client <span class="inline-note">optional · free</span></h3><div class="client-questions">${C.questions.map(q=>{const asked=list(view.questions).find(x=>x.id===q.id)?.asked;return `<article>${btn('ask-client',esc(q.label)+(asked?' '+icon('check'):''),`data-question-id="${q.id}" ${disabled()}`,'button button-light button-wide')}${asked?`<div class="message-bubble"><strong>${esc(q.speaker)}</strong><p>${esc(q.answer)}</p></div>`:''}</article>`;}).join('')}</div>`;}
  function guidesBody(){const q=list(view.guideQuotes).find(q=>q.sectionId===guideId),guide=C.guides.find(g=>g.id===guideId)||C.guides[0],tier=number(view.hints?.[guideId]);const granted=q?.alreadyGranted||practice();return `<p>Optional guidance. Inspection, diagnostic results, controls, accessibility and reading time always remain free.</p><div class="guide-tabs" role="group" aria-label="Guide sections">${C.guides.map(g=>btn('guide-select',esc(g.title),`data-section-id="${g.id}" aria-pressed="${guideId===g.id}"`,'button button-light')).join('')}</div><h3>${esc(guide.title)}</h3><p>${esc(guide.summary)}</p>${!granted?`<div class="guide-quote"><strong>${number(q?.credits)} credits + ${number(q?.minutes)} simulated minutes</strong><p>One acceptance opens all three hints in this section, including reopening. Your resulting contractor fee would be ${number(q?.netFee)} credits. This is separate from the equipment allowance.</p>${btn('consult-guide',`Accept quote & open section`, `data-section-id="${guideId}" data-quote-token="${esc(q?.quoteToken||'')}" ${disabled(!q,true)}`,'button button-primary')}</div>`:`<p class="included">${icon('check')} ${practice()?'All hints are free in rehearsal.':'This section is included. There is no new charge.'}</p><div class="hints">${guide.hints.map(h=>`<article><div class="card-title"><h4>Hint ${h.tier} · ${esc(h.title)}</h4></div>${tier>=h.tier?`<p>${esc(h.text)}</p>`:btn('reveal-hint',`Reveal hint ${h.tier}`,`data-section-id="${guideId}" data-tier="${h.tier}" ${disabled(false,true)}`,'button button-small button-light')}</article>`).join('')}</div>${guide.relatedHelp==='addressing'&&tier>=3?addressingHelp():''}`}<p class="small-copy">${esc(C.economy.guidance)} ${esc(C.economy.note)}</p>`;}
  function addressingHelp(){const a=C.addressing,e=a.workedExample;return `<details data-disclosure="address-example" open><summary>${esc(e.title)}</summary><p>${esc(e.note)}</p>${a.explanation.map(p=>`<p>${esc(p)}</p>`).join('')}<p>Example network: <code>${esc(e.network)}</code><br>Example mask: <code>${esc(e.mask)}</code></p><ol>${e.steps.map(p=>`<li>${esc(p)}</li>`).join('')}</ol><p><strong>${esc(e.applyPrompt)}</strong></p></details>`;}
  function progressBody(){return `<p>${esc(view.storage?.detail||'Progress belongs to this browser profile and site address. Download a copy to move devices.')}</p><div class="progress-actions">${btn('export',icon('download')+' Download progress','data-format="progress"','button button-primary')}${btn('export',icon('note')+' Download readable evidence','data-format="evidence"','button button-light')}${btn('export','Download evidence JSON','data-format="json"','button button-light')}${dirtyCount()?btn('export-drafts','Download all unsubmitted drafts','','button button-light'):''}</div><p class="small-copy">Progress JSON can reopen a job. Evidence is for review; it does not replace a progress file. Draft rescue files clearly identify text and settings that have not been applied.</p><details data-disclosure="import-controls"><summary>Open a downloaded progress file</summary><p>Import replaces the whole active campaign after validation. Save your current progress and drafts first. Earlier clinic files open in the separate bootcamp.</p>${btn('choose-file','Choose progress JSON',disabled(false,true),'button button-light')}<label for="progress-paste">Or paste Opening Shift progress JSON</label><textarea id="progress-paste" rows="4" spellcheck="false" data-draft="import" placeholder="Paste the complete progress JSON here">${esc(pasteText)}</textarea>${btn('review-import','Review pasted import',disabled(!pasteText.trim(),true),'button button-light')}</details><details data-disclosure="recovery-controls"><summary>Rehearsal, recovery & reset</summary><p>Current explanation and setting drafts stay separate from a replacement attempt and remain available as a draft rescue.</p>${practice()?btn('return-client','Return to the independent job',disabled(false,true),'button button-light'):btn('practice','Open free rehearsal',disabled(false,true),'button button-light')}${view.storage?.canTakeControl?btn('confirm-takeover','Review & take control','','button button-light'):''}${view.storage?.canRecover?btn('confirm-recover','Review saved backup',disabled(false,true),'button button-light'):''}${btn('confirm-reset','Review reset',disabled(false,true),'button button-light')}${onClear?btn('confirm-clear','Review clearing local save',disabled(false,true),'button button-light'):''}</details>`;}
  function renderModal(){if(!modal){update('modal','');return;}let title='',body='',footer='';switch(modal.type){case'brief':title='The afternoon shift needs you.';body=`${phoneBody()}<h3>The job</h3><ul>${C.phone.constraints.map(p=>`<li>${esc(p)}</li>`).join('')}</ul>${economy()}<p>${esc(C.modes.client.preparationNote)}</p><p class="small-copy">${esc(C.economy.note)}</p>`;footer=btn('begin-job','Begin client job '+icon('arrow'),disabled(false,true),'button button-primary');break;case'phone':title='A message from the clinic';body=phoneBody();break;case'guides':title='A little support, on your terms.';body=guidesBody();break;case'progress':title='Keep your progress';body=progressBody();break;case'practice':title='Make space to practise.';body=`<p>${esc(C.modes.rehearsal.description)}</p><label for="practice-fixture">Choose a rehearsal</label><select id="practice-fixture">${option('A','Opening setup · first job','A')}${option('B','A changed setup · transfer challenge','A')}</select><p>Opening a fresh rehearsal preserves the independent client job. Earlier rehearsal drafts remain in the separate draft rescue.</p><p class="small-copy">${esc(C.modes.rehearsal.preparationNote)}</p>`;footer=btn('start-practice','Start free rehearsal',disabled(false,true),'button button-primary');break;case'import':title='Replace progress with this file?';body=`<p><strong>${esc(modal.filename||'Pasted progress JSON')}</strong></p><p>The full file is validated before replacement. Cancel or a rejected file keeps your current work. Your unsubmitted drafts remain separate and will not be submitted to the imported job.</p><div class="button-row">${btn('export','Download current progress','data-format="progress"','button button-light')}${dirtyCount()?btn('export-drafts','Download unsubmitted drafts','','button button-light'):''}</div>`;footer=btn('apply-import','Validate & replace current progress',disabled(false,true),'button button-primary');break;case'reset':title='Reset this attempt?';body=`<p>${view.phase==='active'?'This resets the active equipment and evidence. Actual paid guide consultations remain charged; paid equipment is refunded by the engine.':'The delivered job stays frozen. Reset opens a separate free rehearsal.'}</p><p>Your existing drafts stay attached to the earlier attempt and can be downloaded. They will not be placed into the new attempt.</p>${btn('export','Download progress before reset','data-format="progress"','button button-light')}${dirtyCount()?btn('export-drafts','Download draft rescue','','button button-light'):''}`;footer=btn('apply-reset','Reset attempt',disabled(false,true),'button button-danger');break;case'clear':title='Clear this local save?';body=`<p>This removes Opening Shift progress from this browser and creates a new campaign. A downloaded progress file is the way back. The separate earlier clinic is unaffected.</p><p>Unsubmitted drafts remain in this tab for rescue.</p>${btn('export','Download progress before clearing','data-format="progress"','button button-light')}${dirtyCount()?btn('export-drafts','Download draft rescue','','button button-light'):''}`;footer=btn('apply-clear','Clear Opening Shift save',disabled(false,true),'button button-danger');break;case'takeover':case'recover':title=modal.type==='takeover'?'Load the latest saved job?':'Restore the saved backup?';body=`<p>${modal.type==='takeover'?'Taking control loads the latest saved attempt from the other tab.':'Recovery replaces this view with the last valid saved snapshot.'} Download this view and any drafts first if you need them.</p><p>Unsubmitted text will be held for review and will never overwrite another tab’s submitted explanation automatically.</p>${btn('export-raw','Download this progress snapshot','data-format="progress"','button button-light')}${dirtyCount()?btn('export-drafts','Download draft rescue','','button button-light'):''}`;footer=btn(modal.type==='takeover'?'apply-takeover':'apply-recover',modal.type==='takeover'?'Take control & load saved progress':'Restore saved backup',busy?'disabled':'','button button-primary');break;case'draft-blocked':title='Your draft needs your review';body=`<p>${esc(modal.message||'Some explanation drafts could not be saved. They are not part of the submitted record.')}</p><p>Keep the text with a clearly labelled draft rescue, then review it in Handover before submitting.</p>${btn('export-drafts','Download unsubmitted drafts','','button button-primary')}${modal.format?btn('export-raw','Download submitted record only',`data-format="${esc(modal.format)}"`,'button button-light'):''}${btn('review-drafts','Review current draft','','button button-light')}`;break;case'handover':title='Review the handover';body=`${view.ready?'<p class="included">'+icon('check')+' The engine’s current requirements are met.</p>':'<p>Some evidence is still outstanding. The engine will check the real setup again when you submit.</p>'}<ul class="checklist">${list(view.objectives).map(o=>`<li class="${o.met?'met':''}"><span aria-hidden="true">${o.met?'✓':'○'}</span><span>${esc(o.label)}</span></li>`).join('')}</ul>${economy()}<p>Handover freezes this evidence and fee. Written statements and oral arrangements remain pending teacher review.</p>`;footer=btn('handover','Save drafts & submit handover',disabled(),'button button-primary');break;case'about':title='A small model of a real decision';body=`<p>${esc(C.evidenceNote)}</p><ul>${C.boundaries.map(p=>`<li>${esc(p)}</li>`).join('')}</ul><h3>Current learning focus</h3>${Object.values(C.goals).map(g=>`<details data-disclosure="goals-${ident(g.title)}"><summary>${esc(g.title)}</summary><ul>${g.items.map(i=>`<li>${esc(i.text)}</li>`).join('')}</ul></details>`).join('')}<p class="small-copy">Build ${esc(view.buildVersion)}. Internal goal IDs are not official IB outcomes. Original interface and clinic illustration.</p>`;break;default:title='Opening Shift';}
    update('modal',`<div class="dialog-backdrop"><section class="dialog ${modal.type==='guides'?'dialog-wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header><h2 id="dialog-title" class="dialog-title" tabindex="-1">${title}</h2>${btn('close-modal',icon('close'),'aria-label="Close dialog"','icon-button')}</header><div class="dialog-body">${body}</div><footer>${btn('close-modal',footer?'Cancel':'Close','','button button-light')}${footer}</footer></section></div>`);
  }
  function render(){if(closed)return;const f=focusSnapshot();view=getView();const newScope=scope();if(lastScope&&lastScope!==newScope){selectedDeviceId=null;selectedObservationId=null;connection={fromDeviceId:'',fromPortId:'',toDeviceId:'',toPortId:'',itemId:''};}lastScope=newScope;if(!device(selectedDeviceId))selectedDeviceId=view.nurseDeviceId||list(view.devices)[0]?.id;root.classList.toggle('welcome-state',!view.briefReviewed);root.classList.toggle('readonly-state',readonly());update('header',header());update('storage',storage());update('intro',intro());update('focus',focus());update('scene',scene());update('welcome',welcome());root.querySelector('[data-toolbox]').hidden=!view.briefReviewed;update('tabs',tabs());if(view.briefReviewed){update('tool',tool());region('tool').setAttribute('aria-labelledby',`tab-${panel}`);}update('footer',footer());renderFeedback();renderModal();for(const d of root.querySelectorAll('details[data-disclosure]'))if(disclosure.has(d.dataset.disclosure))d.open=true;restoreFocus(f);}
  async function openInspector(id){
    selectedDeviceId=id||view.nurseDeviceId||list(view.devices)[0]?.id;
    panel='devices';render();
    const key=`${scope()}|${selectedDeviceId}`;
    if(!selectedDeviceId||busy||readonly()||frozen()||openedInspections.has(key))return;
    openedInspections.add(key);
    const result=await run({type:'INSPECT_DEVICE',deviceId:selectedDeviceId});
    if(!result?.accepted)openedInspections.delete(key);
  }
  async function run(action,after){if(busy)return {accepted:false,message:'Wait for the current action.'};const heldFocus=focusSnapshot();busy=true;render();try{const result=await send(action);view=getView();if(result?.accepted&&after)await after(result);return result;}catch(error){showStatus('That action could not be completed. Your draft is still available. '+String(error?.message||''),'error');return{accepted:false};}finally{finishWork(heldFocus);}}
  async function saveExplanation(key,{explicit=false}={}){view=getView();const b=bucket(),draft=b.explanations?.[key];if(!draft){if(!explicit)return true;const e=view.explanations?.[key]||{};const result=await send({type:'SAVE_EXPLANATION',key,text:e.text||'',oral:!!e.oral});view=getView();return!!result?.accepted;}if(readonly()||frozen())return false;if(!explicit&&(draft.needsReview||draft.base!==explanationBase(key)))return false;const before={...draft};const result=await send({type:'SAVE_EXPLANATION',key,text:before.text||'',oral:!!before.oral});view=getView();if(!result?.accepted)return false;const current=b.explanations?.[key];if(current&&current.text===before.text&&current.oral===before.oral)delete b.explanations[key];else if(current){current.base=explanationBase(key);current.needsReview=false;}saveDrafts();return true;}
  async function flushExplanations(){view=getView();const keys=Object.keys(explanationDrafts());if(!keys.length)return true;if(readonly()||frozen())return false;for(const key of keys){if(!await saveExplanation(key))return false;}return Object.keys(explanationDrafts()).length===0;}
  async function exportRecord(format,raw=false){if(raw||format==='draft')return onExport(format,format==='draft'?rescueText():undefined);if(busy)return;const heldFocus=focusSnapshot();busy=true;render();try{if(!await flushExplanations()){modal={type:'draft-blocked',format,message:'A draft is unsubmitted, changed during saving, or belongs to a submitted record that changed. Download its rescue copy and review it before replacing evidence.'};render();return;}await onExport(format);if(Object.keys(settingsDrafts()).length)showStatus('Download prepared. Unapplied device settings remain a separate draft; download the draft rescue to retain those values.','info');}finally{finishWork(heldFocus);}}
  function markDraftsForReview(){for(const d of Object.values(explanationDrafts()))d.needsReview=true;saveDrafts();}
  async function replacement(handler){if(busy)return;const heldFocus=focusSnapshot();markDraftsForReview();busy=true;render();try{const result=await handler();view=getView();if(result?.accepted)closeModal();}catch{showStatus('The replacement could not be completed. Current drafts remain available.','error');}finally{finishWork(heldFocus);}}
  function changeDraft(el){const kind=el.dataset.draft;if(kind==='import'){pasteText=el.value;const b=root.querySelector('[data-action="review-import"]');if(b)b.disabled=busy||readonly()||!pasteText.trim();return;}if(kind==='setting'){const d=device(el.dataset.deviceId);if(!d)return;const store=settingsDrafts();const draft=store[d.id]||(store[d.id]={base:JSON.stringify({address:d.address,mask:d.mask,wifiApId:d.wifiApId})});draft[el.dataset.field]=el.value;saveDrafts();const s=root.querySelector(`[data-setting-status="${CSS.escape(d.id)}"]`);if(s)s.innerHTML=badge('Unapplied draft','warn');return;}if(kind==='explanation'||kind==='oral'){const key=el.dataset.key,existing=view.explanations?.[key]||{},draft=explanationDrafts()[key]||(explanationDrafts()[key]={text:existing.text||'',oral:!!existing.oral,base:explanationBase(key),needsReview:false});if(kind==='oral')draft.oral=el.checked;else draft.text=el.value;saveDrafts();const s=root.querySelector(`[data-draft-status="${key}"]`);if(s)s.textContent='Unsubmitted draft · stored only in this tab';}}
  root.addEventListener('input',e=>{if(e.target.dataset.draft)changeDraft(e.target);});
  root.addEventListener('change',e=>{const el=e.target;if(el.dataset.draft)changeDraft(el);if(el.dataset.connection){connection[el.dataset.connection]=el.value;render();}if(el.dataset.action==='device-select')openInspector(el.value);if(el.id==='opening-import-file'&&el.files?.[0]){pendingFile=el.files[0];openModal('import',{filename:pendingFile.name});el.value='';}});
  root.addEventListener('toggle',e=>{if(e.target.matches?.('details[data-disclosure]')){if(e.target.open)disclosure.add(e.target.dataset.disclosure);else disclosure.delete(e.target.dataset.disclosure);}},true);
  root.addEventListener('submit',async e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const type=form.dataset.form,id=form.dataset.deviceId,fd=new FormData(form);if(type==='explanation'){if(busy||readonly()||frozen())return;const heldFocus=focusSnapshot();busy=true;render();try{await saveExplanation(form.dataset.key,{explicit:true});}finally{finishWork(heldFocus);}return;}if(type==='address'){const address=String(fd.get('address')||''),mask=String(fd.get('mask')||'');const draft=settingsDrafts()[id];await run({type:'SET_STATIC_ADDRESS',deviceId:id,address,mask},()=>{if(draft&&draft.address===address)delete draft.address;if(draft&&draft.mask===mask)delete draft.mask;if(draft&&!Object.keys(draft).some(k=>k!=='base'))delete settingsDrafts()[id];saveDrafts();});}if(type==='wifi'){const value=String(fd.get('apDeviceId')||'');await run({type:'ASSOCIATE_WIFI',deviceId:id,apDeviceId:value||null},()=>{const d=settingsDrafts()[id];if(d&&d.wifiApId===value)delete d.wifiApId;if(d&&!Object.keys(d).some(k=>k!=='base'))delete settingsDrafts()[id];saveDrafts();});}if(type==='place')await run({type:'PLACE_DEVICE',deviceId:id,locationId:String(fd.get('locationId'))});if(type==='connect')await run({type:'CONNECT_PORTS',...connection});});
  root.addEventListener('click',async e=>{const target=e.target.closest('[data-action]');if(!target||target.disabled)return;const d=target.dataset,a=d.action;if(a==='panel'){if(d.panel==='devices')return openInspector(selectedDeviceId);panel=d.panel;render();return;}if(a==='select-device')return openInspector(d.deviceId);if(a==='show-observation'){selectedObservationId=d.observationId;render();showStatus('Selected recorded test shown on the clinic plan. Earlier results remain labelled.');return;}if(a==='explanation'){explanationKey=d.key;render();return;}if(a==='guide-select'){guideId=d.sectionId;render();return;}if(a==='close-modal'){closeModal();return;}if(a==='review-brief')return openModal('brief');if(a==='phone')return openModal('phone');if(a==='help')return openModal('guides');if(a==='progress')return openModal('progress');if(a==='practice')return openModal('practice');if(a==='about')return openModal('about');if(a==='review-handover')return openModal('handover');if(a==='confirm-reset')return openModal('reset');if(a==='confirm-clear')return openModal('clear');if(a==='confirm-recover')return openModal('recover');if(a==='confirm-takeover')return openModal('takeover');if(a==='export-drafts')return onExport('draft',rescueText());if(a==='export')return exportRecord(d.format);if(a==='export-raw')return exportRecord(d.format,true);if(a==='review-drafts'){closeModal();panel='handover';render();root.querySelector('#panel-heading')?.focus();return;}if(a==='choose-file'){root.querySelector('#opening-import-file').click();return;}if(a==='review-import'){pendingFile=null;return openModal('import',{filename:'Pasted progress JSON'});}if(a==='apply-import')return replacement(()=>onImport(pendingFile||pasteText));if(a==='apply-reset')return replacement(onReset);if(a==='apply-clear')return replacement(onClear);if(a==='apply-recover')return replacement(onRecover);if(a==='apply-takeover')return replacement(onTakeControl);
    if(a==='begin-job'){await run({type:'REVIEW_BRIEF'},()=>closeModal());return;}if(a==='start-practice'){const fixture=root.querySelector('#practice-fixture')?.value==='B'?'B':'A';await run({type:'START_PRACTICE',fixture},async()=>{await send({type:'REVIEW_BRIEF'});closeModal();panel='equipment';});return;}if(a==='return-client'){await run({type:'RETURN_TO_CLIENT'},()=>{closeModal();panel='equipment';});return;}if(a==='handover'){if(busy)return;const heldFocus=focusSnapshot();busy=true;render();try{if(!await flushExplanations()){modal={type:'draft-blocked',message:'Save or rescue your current explanation drafts before handover.'};return;}const result=await send({type:'REQUEST_HANDOVER'});if(result?.accepted){closeModal();panel='handover';}}finally{finishWork(heldFocus);}return;}
    const actions={
      'ask-client':()=>({type:'ASK_CLIENT',questionId:d.questionId}),'assign-nurse':()=>({type:'ASSIGN_NURSE',itemId:d.itemId}),'buy':()=>({type:'BUY_ITEM',sku:d.sku}),'install':()=>({type:'INSTALL_ITEM',itemId:d.itemId,locationId:'location.equipment'}),'return-item':()=>({type:'RETURN_ITEM',itemId:d.itemId}),'uninstall':()=>({type:'UNINSTALL_ITEM',itemId:d.itemId}),'inspect-device':()=>({type:'INSPECT_DEVICE',deviceId:d.deviceId}),'inspect-cable':()=>({type:'INSPECT_CABLE',itemId:d.itemId}),'power':()=>({type:'POWER_DEVICE',deviceId:d.deviceId,on:d.on==='true'}),'move-nurse':()=>({type:'MOVE_NURSE',locationId:d.locationId}),'probe':()=>({type:'RUN_PROBE',testId:d.testId}),'disconnect':()=>({type:'DISCONNECT_CABLE',cableId:d.cableId}),'policy':()=>({type:'SET_PERMISSIONS',policyId:d.policyId}),'services':()=>({type:'SET_SERVICE_STATE',enabled:d.enabled==='true'}),'consult-guide':()=>({type:'GUIDE_CONSULT',sectionId:d.sectionId,quoteToken:d.quoteToken}),'reveal-hint':()=>({type:'REVEAL_HINT',sectionId:d.sectionId,tier:Number(d.tier)}),'settle':()=>({type:'SETTLE_CONTRACT'})};
    if(actions[a])await run(actions[a](),()=>{if(a==='probe')selectedObservationId=getView().observations?.[0]?.id||null;if(a==='install'){selectedDeviceId=getView().apDeviceId;panel='devices';}if(a==='assign-nurse')selectedDeviceId=getView().nurseDeviceId;});
  });
  root.addEventListener('keydown',e=>{if(e.target.getAttribute('role')==='tab'&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const i=TABS.findIndex(t=>t[0]===panel);panel=TABS[e.key==='Home'?0:e.key==='End'?TABS.length-1:(i+(e.key==='ArrowRight'?1:-1)+TABS.length)%TABS.length][0];render();root.querySelector(`#tab-${panel}`)?.focus();if(panel==='devices')openInspector(selectedDeviceId);return;}if(modal){if(e.key==='Escape'){e.preventDefault();closeModal();return;}if(e.key==='Tab'){const dialog=root.querySelector('.dialog'),items=[...dialog.querySelectorAll('button:not([disabled]),a[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled]),summary,[tabindex="0"]')].filter(x=>!x.closest('[hidden]')&&x.getClientRects().length);if(!items.length){e.preventDefault();return;}if(e.shiftKey&&(document.activeElement===items[0]||document.activeElement===dialog.querySelector('.dialog-title'))){e.preventDefault();items.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus();}}}});
  const beforeUnload=()=>saveDrafts();window.addEventListener('pagehide',beforeUnload);
  render();
  return {render,showStatus,destroy(){closed=true;window.removeEventListener('pagehide',beforeUnload);}};
}
